}
import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import path from 'node:path';

const booksFile = path.join(process.cwd(), 'data', 'books.json');

export async function getBooks() {
  try {
    const contents = await readFile(booksFile, 'utf8');
    const books = JSON.parse(contents);
    return Array.isArray(books) ? books : [];
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

export async function getBook(id) {
  const books = await getBooks();
  return books.find((book) => book.id === id) ?? null;
}

async function saveBooks(books) {
  await mkdir(path.dirname(booksFile), { recursive: true });
  const temporaryFile = `${booksFile}.tmp-${process.pid}-${randomUUID()}`;
  await writeFile(temporaryFile, `${JSON.stringify(books, null, 2)}\n`, 'utf8');
  await rename(temporaryFile, booksFile);
}

export async function addBook({ title, author, notes = '' }) {
  const cleanTitle = typeof title === 'string' ? title.trim() : '';
  const cleanAuthor = typeof author === 'string' ? author.trim() : '';

  if (!cleanTitle || !cleanAuthor) {
    throw new Error('Add a title and an author to save this book.');
  }

  const book = {
    id: randomUUID(),
    title: cleanTitle,
    author: cleanAuthor,
    notes: typeof notes === 'string' ? notes.trim() : '',
    status: 'reading',
    createdAt: new Date().toISOString(),
    finishedAt: null
  };
  const books = await getBooks();
  books.unshift(book);
  await saveBooks(books);
  return book;
}

export async function finishBook(id) {
  const books = await getBooks();
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return null;

  const existing = books[index];
  const updated = {
    ...existing,
    status: 'finished',
    finishedAt: existing.finishedAt ?? new Date().toISOString()
  };
  books[index] = updated;
  await saveBooks(books);
  return updated;
}
'use client';

import Link from 'next/link';
import { useState } from 'react';
import BookCover from './book-cover';

function BookRow({ book, onFinish, isFinishing }) {
  return (
    <article className="book-row">
      <Link className="row-cover-link" href={`/books/${book.id}`} aria-label={`Open ${book.title}`}>
        <BookCover book={book} />
      </Link>
      <div className="row-copy">
        <Link className="book-title-link" href={`/books/${book.id}`}>{book.title}</Link>
        <span className="book-author">{book.author}</span>
      </div>
      {book.status === 'reading' ? (
        <button className="finish-button" type="button" onClick={() => onFinish(book.id)} disabled={isFinishing}>
          {isFinishing ? 'Saving…' : 'Mark finished'}
        </button>
      ) : (
        <span className="finished-check" aria-label="Finished">✓</span>
      )}
    </article>
  );
}

export default function LibraryShelf({ initialBooks }) {
  const [books, setBooks] = useState(initialBooks);
  const [formOpen, setFormOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [finishingId, setFinishingId] = useState(null);
  const [error, setError] = useState('');

  const reading = books.filter((book) => book.status === 'reading');
  const finished = books.filter((book) => book.status === 'finished');

  async function addBook(event) {
    event.preventDefault();
    setSaving(true);
    setError('');
    const form = event.currentTarget;
    const values = Object.fromEntries(new FormData(form));
    try {
      const response = await fetch('/api/books', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(values)
      });
      const result = await response.json();
      if (!response.ok) throw new Error(result.error || 'Could not save this book.');
      setBooks((current) => [result, ...current]);
      form.reset();
      setFormOpen(false);
    } catch (requestError) {
      setError(requestError.message || 'Could not save this book.');
    } finally {
      setSaving(false);
    }
  }

  async function markFinished(id) {
    setFinishingId(id);
    setError('');
    try {
      const response = await fetch(`/api/books/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'finished' })
      });
      const result = await response.json();
      if (!response.ok) throw new Error(result.error || 'Could not update this book.');
      setBooks((current) => current.map((book) => book.id === id ? result : book));
    } catch (requestError) {
      setError(requestError.message || 'Could not update this book.');
    } finally {
      setFinishingId(null);
    }
  }

  return (
    <main className="page-shell">
      <header className="topbar">
        <Link className="brand" href="/" aria-label="Reading Shelf home">
          <span className="brand-mark" aria-hidden="true"><i /><i /><i /></span>
          <span>reading shelf</span>
        </Link>
        <div className="topbar-note"><span className="topbar-spark">✳</span> Your books, your own little corner</div>
      </header>

      <section className="hero">
        <div className="hero-copy">
          <span className="eyebrow">A PERSONAL READING LOG</span>
          <h1>A little shelf for<br />the books that stay.</h1>
          <p>Keep your place, collect your thoughts, and remember what you’ve read.</p>
        </div>
        <div className="hero-aside" aria-hidden="true">
          <div className="hero-sun">✳</div>
          <span>one page at a time</span>
        </div>
      </section>

      <section className="shelf-toolbar" aria-label="Shelf summary">
        <div className="shelf-counts">
          <span><strong>{reading.length.toString().padStart(2, '0')}</strong> IN PROGRESS</span>
          <span className="count-divider" />
          <span><strong>{finished.length.toString().padStart(2, '0')}</strong> FINISHED</span>
        </div>
        <button className="add-button" type="button" onClick={() => { setFormOpen((open) => !open); setError(''); }} aria-expanded={formOpen}>
          <span className="add-plus">{formOpen ? '×' : '+'}</span> {formOpen ? 'Close form' : 'Add a book'}
        </button>
      </section>

      {formOpen && (
        <section className="add-panel" aria-labelledby="add-book-heading">
          <div className="form-intro">
            <span className="eyebrow">MAKE ROOM ON THE SHELF</span>
            <h2 id="add-book-heading">Add a book</h2>
            <p>Every good read starts somewhere.</p>
          </div>
          <form className="book-form" onSubmit={addBook}>
            <label>Title<input name="title" placeholder="The book’s title" required maxLength={180} autoFocus /></label>
            <label>Author<input name="author" placeholder="Who wrote it?" required maxLength={120} /></label>
            <label className="notes-field">Notes <span>(optional)</span><textarea name="notes" placeholder="A thought, a passage, a feeling…" rows="2" maxLength={5000} /></label>
            {error && <p className="form-error" role="alert">{error}</p>}
            <div className="form-actions">
              <button className="text-button" type="button" onClick={() => setFormOpen(false)}>Cancel</button>
              <button className="submit-button" type="submit" disabled={saving}>{saving ? 'Adding…' : 'Add to shelf'} <span>↗</span></button>
            </div>
          </form>
        </section>
      )}

      {error && !formOpen && <p className="global-error" role="alert">{error}</p>}

      <div className="shelf-grid">
        <section className="shelf-section reading-section" aria-labelledby="reading-heading">
          <div className="section-heading">
            <div><span className="eyebrow">RIGHT NOW</span><h2 id="reading-heading">Currently reading</h2></div>
            <span className="section-number">{reading.length.toString().padStart(2, '0')}</span>

